function (deconv, cells_extra = NULL) 
{
    cat("Preprocessing deconvolution features...............................................................\n\n")
    deconv <- deconv %>% data.frame() %>% dplyr::mutate(dplyr::across(dplyr::everything(), 
        ~tidyr::replace_na(.x, 0)))
    deconv_standarized = standardize_celltype_colnames(deconv)
    cat("Checking consistency in deconvolution cell fractions across patients...............................................................\n\n")
    cell_types = get_cell_type_nomenclature()
    if (is.null(cells_extra)) {
        cat("No extra cell types provided. Only the following cell types will be considered:\n", 
            paste0(cell_types, collapse = "\n"), "\n\n")
        cat("If you want to consider other cell types (e.g. from a custom signature) which are not included in the package by default (see README), please provide them in the cells_extra argument.\n")
    }
    cell_types = c(cell_types, cells_extra)
    pattern <- paste0("(_", gsub("\\.", "\\\\.", cell_types), 
        ")$", collapse = "|")
    combinations <- unique(gsub(pattern, "", colnames(deconv_standarized)))
    error = F
    for (i in combinations) {
        idx <- which(startsWith(colnames(deconv_standarized), 
            paste0(i, "_")))
        if (length(idx) > 0) {
            mat = deconv_standarized[, idx, drop = FALSE]
            sums = round(rowSums(mat), 2)
            if (all(sums == 1) == F) {
                cat(paste("\n\nTotal sum across samples of combination", 
                  i, "is not 1! Remember these are proportions and the total should be 1\n"))
                cat("Samples which sum with combination", i, 
                  "is not 1:\n\n", paste0(names(sums)[sums != 
                    1], collapse = "\n"), "\n")
                error = T
            }
            else {
                cat(paste("\nTotal sum across samples of combination", 
                  i, "is", round(sum(mat[1, ]), 2)))
            }
        }
    }
    if (error) {
        warning("\nPlease verify your matrix")
    }
    return(deconv_standarized)
}
